content.text:
No surface change was needed. All five scenarios compile against the existing `h.d.ts` and `kernel.d.ts`, so only the scenario files follow. Four things need saying first:

- **Closure annotations.** Metrics that are referenced inside policies or flows declared before them carry a `MetricRef<…>` type annotation. Policy closures declare `: Model` as their return type. Both avoid circular inference; neither uses an escape hatch.
- **Taste capture in scenario 6.** The trigger fires on the editor's `return` decision at the `editorial` halt, not on the transition to `Returned`. The editor's notes live in the halt's recorded decision, not in the unit's attributes.
- **Scenario 7 is one file, not two modules.** Scenario files may import only from `harness-dsl`, so the shared module becomes a shared block at the top of the file: the accounts, the drain policy and the taste store.
- **Two known gaps remain:**
  - In scenario 9, a redraft after a rejection cannot see the reviewer's notes. A loop body's context types only the steps before the loop.
  - Auto-approved replies count as approval samples, which slightly inflates the approval rate.

=== FILE: scenarios/06-content-taste.ts ===
import { z } from 'zod';
import { H, MetricRef, Metrics, Model, Sample, Window } from 'harness-dsl';
import { sqlite } from 'harness-dsl/sqlite';
import { jsonl } from 'harness-dsl/jsonl';
import { anthropic } from 'harness-dsl/anthropic';
import { contentful } from 'harness-dsl/contentful';
import { claudeCode } from 'harness-dsl/claude-code';
import { local } from 'harness-dsl/local';
import { markdown } from 'harness-dsl/markdown';

const draftAttributes = z.object({
  entryId: z.string(),
  title: z.string(),
  section: z.string(),
  body: z.string(),
});

const Submitted = H.state('Submitted', 'pending');
const InReview = H.state('InReview', 'active');
const WithEditor = H.state('WithEditor', 'active');
const Accepted = H.terminal('Accepted', 'success');
const Returned = H.terminal('Returned', 'neutral');
const Withdrawn = H.terminal('Withdrawn', 'neutral');

const Draft = H.kind('Draft')
  .attributes(draftAttributes)
  .states(Submitted, InReview, WithEditor, Accepted, Returned, Withdrawn)
  .key(draft => draft.entryId)
  .initial(Submitted)
  .onCancelled(Withdrawn);

const reviewer = H.role('reviewer')
  .intents('read')
  .instructions('Critique the draft for structure, accuracy and voice. Cite the passages you object to.');

const tasteKind = H.memory('editorial-taste', 'taste');
const factLessonKind = H.memory('fact-check-lesson', 'experience');

const taste = H.journal('taste', tasteKind)
  .store(jsonl.memoryStore({ path: '.harness/taste.jsonl' }))
  .recall({ by: 'specificity', limit: 15 })
  .readBy(reviewer);

const factLessons = H.journal('fact-lessons', factLessonKind)
  .store(jsonl.memoryStore({ path: '.harness/fact-lessons.jsonl' }))
  .recall({ by: 'specificity', limit: 10 })
  .readBy(reviewer);

const apiAccount = anthropic.account('api', { apiKey: H.env('ANTHROPIC_API_KEY') });
const reviewers = H.pool('reviewers').accounts(apiAccount);

const firstIncumbent = anthropic.model('opus', { id: 'claude-opus-4-1' });
const secondIncumbent = anthropic.model('sonnet', { id: 'claude-sonnet-4-5' });
const challenger = anthropic.model('haiku', { id: 'claude-haiku-4-5' });

const comparisonWindow: Window = { lastDays: 90 };

function weakerIncumbent(metrics: Metrics): string | undefined {
  const first = metrics.rate(critiqueActedOn, { group: firstIncumbent.name, window: comparisonWindow });
  const second = metrics.rate(critiqueActedOn, { group: secondIncumbent.name, window: comparisonWindow });
  if (first.samples < 50 || second.samples < 50 || first.rate === second.rate) return undefined;
  return first.rate < second.rate ? firstIncumbent.name : secondIncumbent.name;
}

const firstSlot = H.policy.model(
  'first-reviewer-model',
  [firstIncumbent, challenger],
  (ctx): Model => (weakerIncumbent(ctx.metrics) === firstIncumbent.name ? challenger : firstIncumbent),
);

const secondSlot = H.policy.model(
  'second-reviewer-model',
  [secondIncumbent, challenger],
  (ctx): Model => (weakerIncumbent(ctx.metrics) === secondIncumbent.name ? challenger : secondIncumbent),
);

const critique = z.object({
  critique: z.string(),
  points: z.array(z.string()),
});

const reviewerFirst = H.agent('reviewer-first').role(reviewer).model(firstSlot).pool(reviewers).output(critique);
const reviewerSecond = H.agent('reviewer-second').role(reviewer).model(secondSlot).pool(reviewers).output(critique);

const desk = local.runner('editorial-desk').slots(4);

const factFindings = z.object({
  issues: z.array(z.string()),
  repeatLesson: z.string().optional(),
});

const factCheck = H.command('fact-check')
  .input(z.object({ section: z.string(), body: z.string() }))
  .argv(input => ['fact-check', '--section', input.section, '--text', input.body])
  .output(factFindings)
  .runner(desk);

const mergeCritiques = H.command('merge-critiques')
  .input(z.object({ first: critique, second: critique, facts: factFindings }))
  .argv(input => ['merge-critiques', '--json', JSON.stringify(input)])
  .output(z.object({ summary: z.string() }))
  .runner(desk);

const editorialDecision = z.object({
  action: z.enum(['accept', 'return']),
  notes: z.string(),
  scope: z.enum(['all', 'section']),
  actedOn: z.array(z.enum(['first', 'second'])),
});

const reviewFlow = H.flow('review-draft')
  .input(draftAttributes)
  .step('critiqueFirst', reviewerFirst, ctx => ({
    task: `Critique "${ctx.unit.attributes.title}":\n\n${ctx.unit.attributes.body}`,
    resources: [`section/${ctx.unit.attributes.section}`],
  }))
  .step('critiqueSecond', reviewerSecond, ctx => ({
    task: `Critique "${ctx.unit.attributes.title}":\n\n${ctx.unit.attributes.body}`,
    resources: [`section/${ctx.unit.attributes.section}`],
  }))
  .step('factCheck', factCheck, ctx => ({ section: ctx.unit.attributes.section, body: ctx.unit.attributes.body }))
  .step('merge', mergeCritiques, ctx => ({
    first: ctx.steps.critiqueFirst,
    second: ctx.steps.critiqueSecond,
    facts: ctx.steps.factCheck,
  }))
  .halt('editorial', {
    ask: ctx => `Accept or return "${ctx.unit.attributes.title}" (${ctx.unit.attributes.section}).\n\n${ctx.steps.merge.summary}`,
    decision: editorialDecision,
  })
  .exit('accepted', ctx => ctx.steps.editorial.action === 'accept')
  .exit('returned');

const cmsToken = H.env('CONTENTFUL_TOKEN');

const drafts = H.lane('drafts', Draft)
  .supply(contentful.drafts({ space: 'newsroom', token: cmsToken, everyMinutes: 10 }), (entry, to) =>
    to.create({ entryId: entry.id, title: entry.title, section: entry.section, body: entry.body }),
  )
  .store(contentful.store({ space: 'newsroom', token: cmsToken }))
  .handler(reviewFlow, {
    exits: { accepted: Accepted, returned: Returned },
    during: {
      critiqueFirst: InReview,
      critiqueSecond: InReview,
      factCheck: InReview,
      merge: InReview,
      editorial: WithEditor,
    },
  });

const critiqueActedOn: MetricRef<'rate'> = H.metric('critique-acted-on', H.when.step(drafts, 'editorial')).samples(
  event => {
    const decision = event.output;
    if (decision === undefined) return [];
    const samples: Sample[] = [];
    const firstModel = event.models.critiqueFirst;
    const secondModel = event.models.critiqueSecond;
    if (firstModel !== undefined) samples.push({ group: firstModel, hit: decision.actedOn.includes('first') });
    if (secondModel !== undefined) samples.push({ group: secondModel, hit: decision.actedOn.includes('second') });
    return samples;
  },
);

const editorNotesToTaste = H.trigger('editor-notes-to-taste')
  .on(H.when.step(drafts, 'editorial', { if: event => event.output?.action === 'return' }))
  .record(taste, event => {
    const decision = event.output;
    if (decision === undefined || decision.notes === '') return undefined;
    const section = event.unit.attributes.section;
    return {
      text: `When reviewing a draft, ${decision.notes}, because the editor returned "${event.unit.attributes.title}" for it.`,
      status: 'candidate',
      when: decision.scope === 'section' ? { kinds: [Draft], resources: [`section/${section}`] } : { kinds: [Draft] },
    };
  });

const repeatMistakeToExperience = H.trigger('repeat-mistake-to-experience')
  .on(H.when.step(drafts, 'factCheck', { if: event => event.output?.repeatLesson !== undefined }))
  .record(factLessons, event => {
    const lesson = event.output?.repeatLesson;
    return lesson === undefined ? undefined : { text: lesson, when: { kinds: [Draft], roles: [reviewer] } };
  });

const editorDesk = claudeCode.supervisor('editor-desk', {
  grants: [
    H.ops.workRead,
    H.ops.blockersResolve,
    H.ops.memoryRead,
    H.ops.memoryWrite,
    H.ops.memoryCurate,
    H.ops.telemetryRead,
  ],
});

const content = H.harness('content-review')
  .ledger(sqlite.ledger({ path: '.harness/ledger.sqlite' }))
  .lanes(drafts)
  .journals(taste, factLessons)
  .triggers(editorNotesToTaste, repeatMistakeToExperience)
  .metrics(critiqueActedOn)
  .scheduler(H.scheduler('content').priority(drafts))
  .clients(editorDesk)
  .observers(markdown.board({ path: '.harness/board.md' }), markdown.telemetry({ path: '.harness/telemetry.md' }));

void content.start();
=== END ===

=== FILE: scenarios/07-multi-tenant.ts ===
import { z } from 'zod';
import { H, Model, Role } from 'harness-dsl';
import { sqlite } from 'harness-dsl/sqlite';
import { jsonl } from 'harness-dsl/jsonl';
import { claudeCode } from 'harness-dsl/claude-code';
import { anthropic } from 'harness-dsl/anthropic';
import { linear } from 'harness-dsl/linear';
import { folder } from 'harness-dsl/folder';
import { git } from 'harness-dsl/git';
import { local } from 'harness-dsl/local';
import { markdown } from 'harness-dsl/markdown';

const subscriptionOne = claudeCode.subscription('max-one', { token: H.env('CLAUDE_MAX_ONE_TOKEN') });
const subscriptionTwo = claudeCode.subscription('max-two', { token: H.env('CLAUDE_MAX_TWO_TOKEN') });
const subscriptionThree = claudeCode.subscription('max-three', { token: H.env('CLAUDE_MAX_THREE_TOKEN') });
const apiAccount = anthropic.account('api', { apiKey: H.env('ANTHROPIC_API_KEY') });

const sharedQuotaPath = '/home/owner/.harness/quota.sqlite';

const soonestExpiring = H.policy.account('soonest-expiring', ctx => {
  const eligible = ctx.candidates.filter(
    account =>
      account.shareUsed < account.shareCap &&
      (account.cooldownUntil === undefined || account.cooldownUntil <= ctx.now),
  );
  const ordered = [...eligible].sort((a, b) => a.windowResetsAt.getTime() - b.windowResetsAt.getTime());
  return ordered[0];
});

function subscriptionPool(name: string, fraction: number) {
  return H.pool(name)
    .accounts(subscriptionOne, subscriptionTwo, subscriptionThree)
    .share(subscriptionOne, fraction)
    .share(subscriptionTwo, fraction)
    .share(subscriptionThree, fraction)
    .drain(soonestExpiring)
    .fallback(apiAccount);
}

const tasteKind = H.memory('owner-taste', 'taste');
const experienceKind = H.memory('experience', 'experience');
const sharedTasteStore = jsonl.memoryStore({ path: '/home/owner/.harness/taste.jsonl' });

function tasteJournal(...readers: Role[]) {
  return H.journal('taste', tasteKind).store(sharedTasteStore).recall({ by: 'specificity', limit: 12 }).readBy(...readers);
}

const sonnet = claudeCode.model('sonnet', { id: 'claude-sonnet-4-5' });
const opus = claudeCode.model('opus', { id: 'claude-opus-4-1' });

const codingPool = subscriptionPool('coding-subscriptions', 0.6);
const codingRunner = local.runner('coding-box').slots(4);

const workAttributes = z.object({
  title: z.string(),
  description: z.string(),
  issueId: z.string().optional(),
});

const Queued = H.state('Queued', 'pending');
const Building = H.state('Building', 'active');
const Auditing = H.state('Auditing', 'active');
const Planning = H.state('Planning', 'active');
const Delivering = H.state('Delivering', 'active');
const Done = H.terminal('Done', 'success');
const Exhausted = H.terminal('Exhausted', 'failure');
const Abandoned = H.terminal('Abandoned', 'neutral');

const Bug = H.kind('Bug')
  .attributes(workAttributes)
  .states(Queued, Building, Auditing, Done, Exhausted, Abandoned)
  .key(work => work.issueId ?? work.title)
  .initial(Queued)
  .onCancelled(Abandoned);

const Feature = H.kind('Feature')
  .attributes(workAttributes)
  .states(Queued, Building, Auditing, Done, Exhausted, Abandoned)
  .key(work => work.issueId ?? work.title)
  .initial(Queued)
  .onCancelled(Abandoned);

const Epic = H.kind('Epic')
  .attributes(workAttributes)
  .states(Queued, Planning, Delivering, Done, Exhausted, Abandoned)
  .key(work => work.issueId ?? work.title)
  .initial(Queued)
  .onCancelled(Abandoned);

const Due = H.state('Due', 'pending');
const Probing = H.state('Probing', 'active');
const Healthy = H.terminal('Healthy', 'success');
const Unhealthy = H.terminal('Unhealthy', 'failure');

const heartbeatAttributes = z.object({ at: z.string() });

const ServiceHeartbeat = H.kind('ServiceHeartbeat')
  .attributes(heartbeatAttributes)
  .states(Due, Probing, Healthy, Unhealthy)
  .key(beat => beat.at)
  .initial(Due);

const builder = H.role('builder')
  .intents('read', 'edit', 'run', 'search', 'halt')
  .instructions('Implement the change. Halt for the owner when a product decision is needed.');
const auditor = H.role('auditor')
  .intents('read', 'run', 'search', 'record')
  .instructions('Find deficits against the task. Record lessons that will help the next builder.');
const planner = H.role('planner')
  .intents('read', 'search')
  .instructions('Decompose the epic into independently shippable features.');

const projectChecks = H.command('project-checks').argv(['npm', 'run', 'check']).runner(codingRunner);

const builderModel = H.policy.model('builder-model', [sonnet, opus], (ctx): Model => {
  const record = ctx.metrics.attempts({ of: ctx.kind, model: sonnet, window: { lastDays: 14 } });
  return record.samples >= 20 && record.successRate < 0.85 ? opus : sonnet;
});

const builderAgent = H.agent('builder')
  .role(builder)
  .model(builderModel)
  .pool(codingPool)
  .workspace(git.worktree({ repo: '.', base: 'main' }))
  .guards(H.guard.lease(), H.guard.beforeStop(projectChecks))
  .output(z.object({ summary: z.string(), filesChanged: z.array(z.string()) }));

const auditorAgent = H.agent('auditor')
  .role(auditor)
  .model(opus)
  .pool(codingPool)
  .output(z.object({ deficits: z.array(z.string()) }));

const plannerAgent = H.agent('planner')
  .role(planner)
  .model(opus)
  .pool(codingPool)
  .output(z.object({ features: z.array(z.object({ title: z.string(), description: z.string() })) }));

const buildAndAudit = H.flow('build-and-audit')
  .input(z.object({ title: z.string(), description: z.string() }))
  .params(z.object({ rounds: z.number() }))
  .loop(
    'rounds',
    round =>
      round
        .step('build', builderAgent, ctx => ({
          task: `${ctx.unit.attributes.title}\n\n${ctx.unit.attributes.description}`,
        }))
        .step('audit', auditorAgent, ctx => ({
          task: `Audit the change for "${ctx.unit.attributes.title}": ${ctx.steps.build.summary}`,
          resources: ctx.steps.build.filesChanged,
        })),
    {
      max: ctx => ctx.params.rounds,
      until: ctx => ctx.steps.audit.deficits.length === 0,
    },
  )
  .exit('done', ctx => ctx.steps.audit.deficits.length === 0)
  .exit('exhausted');

const linearKey = H.env('LINEAR_API_KEY');
const trackerStore = linear.store({
  apiKey: linearKey,
  team: 'ENG',
  states: {
    Queued: 'Todo',
    Building: 'In Progress',
    Auditing: 'In Review',
    Planning: 'In Progress',
    Delivering: 'In Progress',
    Done: 'Done',
    Exhausted: 'Blocked',
    Abandoned: 'Canceled',
  },
});

const bugs = H.lane('bugs', Bug)
  .supply(linear.issues({ apiKey: linearKey, team: 'ENG', labels: ['bug'] }), (issue, to) =>
    to.create({ title: issue.title, description: issue.description, issueId: issue.identifier }),
  )
  .supply(folder.files({ path: 'bugs', glob: '*.md' }), (file, to) =>
    to.create({ title: file.name, description: file.body }),
  )
  .supply(H.operator)
  .store(trackerStore)
  .handler(buildAndAudit, {
    exits: { done: Done, exhausted: Exhausted },
    during: { build: Building, audit: Auditing },
    params: { rounds: 3 },
  });

const features = H.lane('features', Feature)
  .supply(linear.issues({ apiKey: linearKey, team: 'ENG', labels: ['feature'] }), (issue, to) =>
    to.create({ title: issue.title, description: issue.description, issueId: issue.identifier }),
  )
  .supply(H.operator)
  .store(trackerStore)
  .handler(buildAndAudit, {
    exits: { done: Done, exhausted: Exhausted },
    during: { build: Building, audit: Auditing },
    params: { rounds: 5 },
  });

const deliverEpic = H.flow('deliver-epic')
  .input(workAttributes)
  .step('plan', plannerAgent, ctx => ({ task: `${ctx.unit.attributes.title}\n\n${ctx.unit.attributes.description}` }))
  .spawn('deliver', features, ctx => ctx.steps.plan.features)
  .exit('completed', ctx => ctx.steps.deliver.every(child => child.verdict === 'success'))
  .exit('incomplete');

const epics = H.lane('epics', Epic)
  .supply(linear.issues({ apiKey: linearKey, team: 'ENG', labels: ['epic'] }), (issue, to) =>
    to.create({ title: issue.title, description: issue.description, issueId: issue.identifier }),
  )
  .store(trackerStore)
  .handler(deliverEpic, {
    exits: { completed: Done, incomplete: Exhausted },
    during: { plan: Planning, deliver: Delivering },
  });

const serviceHealth = H.command('service-health')
  .argv(['./scripts/health.sh'])
  .acceptExitCodes(0, 1)
  .runner(codingRunner);

const heartbeatFlow = H.flow('heartbeat')
  .input(heartbeatAttributes)
  .step('probe', serviceHealth)
  .exit('healthy', ctx => ctx.steps.probe.exitCode === 0)
  .exit('unhealthy');

const heartbeats = H.lane('heartbeats', ServiceHeartbeat)
  .supply(H.clock('every-five-minutes').every({ minutes: 5 }), (tick, to) => to.create({ at: tick.at.toISOString() }))
  .handler(heartbeatFlow, { exits: { healthy: Healthy, unhealthy: Unhealthy }, during: { probe: Probing } });

const unhealthyHeartbeatOpensBug = H.trigger('unhealthy-heartbeat-opens-bug')
  .on(H.when.transition(heartbeats, { to: Unhealthy }))
  .create(bugs, event => ({
    title: `Service heartbeat failed at ${event.unit.attributes.at}`,
    description: 'The five-minute service heartbeat probe reported the service unhealthy.',
  }));

const codingExperience = H.journal('experience', experienceKind)
  .store(jsonl.memoryStore({ path: 'coding/.harness/experience.jsonl' }))
  .recall({ by: 'specificity', limit: 10 })
  .readBy(builder, auditor)
  .recordedBy(auditor);

const productionHealthProbe = H.operation(
  'production-health-probe',
  H.command('production-health').argv(['./scripts/prod-health.sh']).runner(codingRunner),
);

const coding = H.harness('coding-team')
  .ledger(sqlite.ledger({ path: 'coding/.harness/ledger.sqlite', quotaPath: sharedQuotaPath }))
  .lanes(heartbeats, bugs, features, epics)
  .journals(codingExperience, tasteJournal(builder, planner))
  .triggers(unhealthyHeartbeatOpensBug)
  .scheduler(
    H.scheduler('coding')
      .priority(heartbeats, bugs, features, epics)
      .wip(bugs, 2)
      .wip(epics, 1)
      .boost(features, { afterMinutes: 240 }),
  )
  .clients(
    claudeCode.supervisor('coding-supervisor', {
      endpoint: 'coding',
      grants: [
        H.ops.workRead,
        H.ops.workCreate,
        H.ops.workUpdate,
        H.ops.workCancel,
        H.ops.blockersResolve,
        H.ops.memoryRead,
        H.ops.memoryWrite,
        H.ops.telemetryRead,
        H.ops.accountsRead,
        H.ops.accountsShare,
        productionHealthProbe,
      ],
    }),
  )
  .observers(
    markdown.board({ path: 'coding/.harness/board.md' }),
    markdown.telemetry({ path: 'coding/.harness/telemetry.md' }),
  );

const docsPool = subscriptionPool('docs-subscriptions', 0.3);
const docsRunner = local.runner('docs-box').slots(2);

const docAttributes = z.object({ path: z.string(), title: z.string(), body: z.string() });

const Writing = H.state('Writing', 'active');
const LinkChecking = H.state('LinkChecking', 'active');
const Published = H.terminal('Published', 'success');
const Broken = H.terminal('Broken', 'failure');

const DocPage = H.kind('DocPage')
  .attributes(docAttributes)
  .states(Queued, Writing, LinkChecking, Published, Broken, Abandoned)
  .key(page => page.path)
  .initial(Queued)
  .onCancelled(Abandoned);

const writer = H.role('writer')
  .intents('read', 'edit', 'search')
  .instructions('Write or revise the documentation page so that every link resolves.');

const writerAgent = H.agent('writer')
  .role(writer)
  .model(sonnet)
  .pool(docsPool)
  .workspace(git.worktree({ repo: 'docs', base: 'main' }))
  .output(z.object({ summary: z.string() }));

const linkCheck = H.command('link-check')
  .input(z.object({ path: z.string() }))
  .argv(input => ['link-check', input.path])
  .acceptExitCodes(0, 2)
  .runner(docsRunner);

const writePage = H.flow('write-page')
  .input(docAttributes)
  .loop(
    'revise',
    pass =>
      pass
        .step('write', writerAgent, ctx => ({
          task: `Revise ${ctx.unit.attributes.path} ("${ctx.unit.attributes.title}").`,
          resources: [ctx.unit.attributes.path],
        }))
        .step('linkCheck', linkCheck, ctx => ({ path: ctx.unit.attributes.path })),
    { max: 3, until: ctx => ctx.steps.linkCheck.exitCode === 0 },
  )
  .exit('published', ctx => ctx.steps.linkCheck.exitCode === 0)
  .exit('broken');

const docPages = H.lane('doc-pages', DocPage)
  .supply(folder.files({ path: 'docs', glob: '**/*.md' }), (file, to) =>
    to.create({ path: file.path, title: file.name, body: file.body }),
  )
  .store(folder.frontmatter({ path: 'docs' }))
  .handler(writePage, {
    exits: { published: Published, broken: Broken },
    during: { write: Writing, linkCheck: LinkChecking },
  });

const docsExperience = H.journal('experience', experienceKind)
  .store(jsonl.memoryStore({ path: 'docs/.harness/experience.jsonl' }))
  .recall({ by: 'specificity', limit: 10 })
  .readBy(writer);

const docs = H.harness('documentation')
  .ledger(sqlite.ledger({ path: 'docs/.harness/ledger.sqlite', quotaPath: sharedQuotaPath }))
  .lanes(docPages)
  .journals(docsExperience, tasteJournal(writer))
  .scheduler(H.scheduler('docs').priority(docPages))
  .clients(
    claudeCode.supervisor('docs-supervisor', {
      endpoint: 'docs',
      grants: [
        H.ops.workRead,
        H.ops.workCreate,
        H.ops.blockersResolve,
        H.ops.memoryRead,
        H.ops.memoryWrite,
        H.ops.telemetryRead,
        H.ops.accountsRead,
        H.ops.accountsShare,
      ],
    }),
  )
  .observers(markdown.board({ path: 'docs/.harness/board.md' }), markdown.telemetry({ path: 'docs/.harness/telemetry.md' }));

void coding.start();
void docs.start();
=== END ===

=== FILE: scenarios/08-hostile-lifecycles.ts ===
import { z } from 'zod';
import { H } from 'harness-dsl';
import { sqlite } from 'harness-dsl/sqlite';
import { anthropic } from 'harness-dsl/anthropic';
import { claudeCode } from 'harness-dsl/claude-code';
import { webhook } from 'harness-dsl/webhook';
import { local } from 'harness-dsl/local';
import { markdown } from 'harness-dsl/markdown';

const apiAccount = anthropic.account('api', { apiKey: H.env('ANTHROPIC_API_KEY') });
const pool = H.pool('api').accounts(apiAccount);
const strong = anthropic.model('sonnet', { id: 'claude-sonnet-4-5' });
const box = local.runner('ops-box').slots(4);
const store = sqlite.store({ path: '.harness/units.sqlite' });

const experimentAttributes = z.object({
  experiment: z.string(),
  variantA: z.string(),
  variantB: z.string(),
});

const Proposed = H.state('Proposed', 'pending');
const Observing = H.state('Observing', 'active');
const Analysing = H.state('Analysing', 'active');
const AWins = H.terminal('AWins', 'success');
const BWins = H.terminal('BWins', 'success');
const Inconclusive = H.terminal('Inconclusive', 'neutral');
const Withdrawn = H.terminal('Withdrawn', 'neutral');

const Experiment = H.kind('Experiment')
  .attributes(experimentAttributes)
  .states(Proposed, Observing, Analysing, AWins, BWins, Inconclusive, Withdrawn)
  .key(experiment => experiment.experiment)
  .initial(Proposed)
  .onCancelled(Withdrawn);

const measure = H.command('measure-experiment')
  .input(z.object({ experiment: z.string() }))
  .argv(input => ['./experiments/measure', input.experiment])
  .output(z.object({ a: z.number(), b: z.number() }))
  .runner(box);

const analyse = H.command('analyse-experiment')
  .input(z.object({ experiment: z.string() }))
  .argv(input => ['./experiments/analyse', input.experiment])
  .output(z.object({ winner: z.enum(['a', 'b', 'none']) }))
  .runner(box);

const experimentFlow = H.flow('run-experiment')
  .input(experimentAttributes)
  .loop(
    'observe',
    hour =>
      hour
        .step('measure', measure, ctx => ({ experiment: ctx.unit.attributes.experiment }))
        .wait('nextHour', { ms: 3_600_000 }),
    { max: 24 * 14 },
  )
  .step('analyse', analyse, ctx => ({ experiment: ctx.unit.attributes.experiment }))
  .exit('aWins', ctx => ctx.steps.analyse.winner === 'a')
  .exit('bWins', ctx => ctx.steps.analyse.winner === 'b')
  .exit('inconclusive');

const experiments = H.lane('experiments', Experiment)
  .supply(H.operator)
  .store(store)
  .handler(experimentFlow, {
    exits: { aWins: AWins, bWins: BWins, inconclusive: Inconclusive },
    during: { observe: Observing, analyse: Analysing },
  });

const tenancyAttributes = z.object({ customerId: z.string(), plan: z.string() });

const DueForReview = H.state('DueForReview', 'pending');
const Reviewing = H.state('Reviewing', 'active');
const Current = H.state('Current', 'waiting');
const Suspended = H.state('Suspended', 'waiting');
const Churned = H.terminal('Churned', 'neutral');

const Tenancy = H.kind('Tenancy')
  .attributes(tenancyAttributes)
  .states(DueForReview, Reviewing, Current, Suspended, Churned)
  .key(tenancy => tenancy.customerId)
  .initial(DueForReview);

const reviewDue = H.signal('review-due');
const suspend = H.signal('suspend');
const reinstate = H.signal('reinstate');
const churn = H.signal('churn');

const usageReport = H.command('usage-report')
  .input(z.object({ customerId: z.string() }))
  .argv(input => ['./billing/usage', input.customerId])
  .output(z.object({ seats: z.number(), monthlyUsd: z.number(), trend: z.string() }))
  .runner(box);

const accountManager = H.role('account-manager')
  .intents('read')
  .instructions('Summarise the month of usage in plain language and say whether an upsell is warranted.');

const summaryAgent = H.agent('tenancy-summary')
  .role(accountManager)
  .model(strong)
  .pool(pool)
  .output(z.object({ summary: z.string() }));

const tenancyReview = H.flow('tenancy-review')
  .input(tenancyAttributes)
  .step('usage', usageReport, ctx => ({ customerId: ctx.unit.attributes.customerId }))
  .step('summary', summaryAgent, ctx => ({
    task: `Customer ${ctx.unit.attributes.customerId} on ${ctx.unit.attributes.plan}: ${ctx.steps.usage.seats} seats, $${ctx.steps.usage.monthlyUsd}/month, trend ${ctx.steps.usage.trend}.`,
  }))
  .halt('upsell', {
    ask: ctx => `Upsell ${ctx.unit.attributes.customerId}?\n\n${ctx.steps.summary.summary}`,
    decision: z.object({ upsell: z.boolean(), note: z.string() }),
  })
  .exit('reviewed');

const billingEvents = webhook.json('billing-events', {
  port: H.slot.port(1),
  path: '/billing',
  secret: H.env('BILLING_WEBHOOK_SECRET'),
  payload: z.object({
    type: z.enum(['signup', 'suspended', 'reinstated', 'churned']),
    customerId: z.string(),
    plan: z.string(),
  }),
});

const tenancies = H.lane('tenancies', Tenancy)
  .supply(billingEvents, (event, to) => {
    if (event.type === 'signup') return to.create({ customerId: event.customerId, plan: event.plan });
    if (event.type === 'suspended') return to.signal(suspend, event.customerId, {});
    if (event.type === 'reinstated') return to.signal(reinstate, event.customerId, {});
    return to.signal(churn, event.customerId, {});
  })
  .supply(H.clock('monthly-review').at('09:00', { on: 1 }), (tick, to) =>
    to.signal(reviewDue, unit => unit.state === 'Current', {}),
  )
  .store(store)
  .handler(tenancyReview, {
    exits: { reviewed: Current },
    during: { usage: Reviewing, summary: Reviewing, upsell: Reviewing },
  })
  .on(reviewDue, { enter: DueForReview })
  .on(suspend, { enter: Suspended })
  .on(reinstate, { enter: Current })
  .on(churn, { enter: Churned });

const negotiationAttributes = z.object({
  vendor: z.string(),
  item: z.string(),
  targetPrice: z.number(),
  expiresAt: z.string(),
  round: z.number(),
  lastVendorMessage: z.string(),
});

const Drafting = H.state('Drafting', 'pending');
const Negotiating = H.state('Negotiating', 'active');
const AwaitingVendor = H.state('AwaitingVendor', 'waiting');
const Agreed = H.terminal('Agreed', 'success');
const WalkedAwayByUs = H.terminal('WalkedAwayByUs', 'neutral');
const WalkedAwayByThem = H.terminal('WalkedAwayByThem', 'neutral');
const Expired = H.terminal('Expired', 'neutral');

const Negotiation = H.kind('Negotiation')
  .attributes(negotiationAttributes)
  .states(Drafting, Negotiating, AwaitingVendor, Agreed, WalkedAwayByUs, WalkedAwayByThem, Expired)
  .key(negotiation => `${negotiation.vendor}/${negotiation.item}`)
  .initial(Drafting);

const vendorCountered = H.signal('vendor-countered').payload(z.object({ message: z.string() }));
const vendorAccepted = H.signal('vendor-accepted');
const vendorWalkedAway = H.signal('vendor-walked-away');
const expire = H.signal('expire');

const negotiator = H.role('negotiator')
  .intents('read')
  .instructions('Draft the next move in the procurement negotiation: a counter-offer, acceptance, or walking away.');

const negotiatorAgent = H.agent('negotiator')
  .role(negotiator)
  .model(strong)
  .pool(pool)
  .output(z.object({ move: z.enum(['offer', 'accept', 'walkAway']), message: z.string() }));

const sendToVendor = H.command('send-to-vendor')
  .input(z.object({ vendor: z.string(), message: z.string() }))
  .argv(input => ['./procurement/send', input.vendor, input.message])
  .runner(box);

const negotiationRound = H.flow('negotiation-round')
  .input(negotiationAttributes)
  .step('next', negotiatorAgent, ctx => ({
    task: `Round ${ctx.unit.attributes.round} with ${ctx.unit.attributes.vendor} for ${ctx.unit.attributes.item}, target $${ctx.unit.attributes.targetPrice}. Vendor said: ${ctx.unit.attributes.lastVendorMessage}`,
  }))
  .step('send', sendToVendor, ctx => ({ vendor: ctx.unit.attributes.vendor, message: ctx.steps.next.message }), {
    afterCrash: 'park',
  })
  .exit('agreed', ctx => ctx.steps.next.move === 'accept')
  .exit('walkedAway', ctx => ctx.steps.next.move === 'walkAway')
  .exit('offered');

const vendorReplies = webhook.json('vendor-replies', {
  port: H.slot.port(2),
  path: '/vendor',
  secret: H.env('VENDOR_WEBHOOK_SECRET'),
  payload: z.object({
    negotiation: z.string(),
    reply: z.enum(['counter', 'accept', 'walkAway']),
    message: z.string(),
  }),
});

const negotiations = H.lane('negotiations', Negotiation)
  .supply(H.operator)
  .supply(vendorReplies, (event, to) => {
    if (event.reply === 'counter') return to.signal(vendorCountered, event.negotiation, { message: event.message });
    if (event.reply === 'accept') return to.signal(vendorAccepted, event.negotiation, {});
    return to.signal(vendorWalkedAway, event.negotiation, {});
  })
  .store(store)
  .handler(negotiationRound, {
    exits: { agreed: Agreed, walkedAway: WalkedAwayByUs, offered: AwaitingVendor },
    during: { next: Negotiating, send: Negotiating },
  })
  .on(vendorCountered, {
    update: (attrs, payload) => ({ ...attrs, round: attrs.round + 1, lastVendorMessage: payload.message }),
    enter: Drafting,
  })
  .on(vendorAccepted, { enter: Agreed })
  .on(vendorWalkedAway, { enter: WalkedAwayByThem })
  .on(expire, { enter: Expired });

const negotiationExpiry = H.trigger('negotiation-expiry')
  .on(H.when.timer(negotiations, { at: unit => new Date(unit.attributes.expiresAt) }))
  .signal(expire, negotiations, event => ({ key: event.unit.key, payload: {} }));

const scheduler = H.scheduler('lifecycles')
  .priority(negotiations, tenancies, experiments)
  .admit(experiments, ctx => {
    const record = ctx.metrics.outcomes({ of: experiments, window: { lastDays: 180 } });
    if (record.terminal < 10) return true;
    const inconclusiveShare = record.byState.Inconclusive / record.terminal;
    return inconclusiveShare < 0.5 || ctx.active(experiments) === 0;
  });

const lifecycles = H.harness('lifecycles')
  .ledger(sqlite.ledger({ path: '.harness/ledger.sqlite' }))
  .lanes(experiments, tenancies, negotiations)
  .triggers(negotiationExpiry)
  .scheduler(scheduler)
  .clients(
    claudeCode.supervisor('lifecycle-supervisor', {
      grants: [H.ops.workRead, H.ops.workCreate, H.ops.workSignal, H.ops.workCancel, H.ops.blockersResolve, H.ops.telemetryRead],
    }),
  )
  .observers(markdown.board({ path: '.harness/board.md' }), markdown.telemetry({ path: '.harness/telemetry.md' }));

void lifecycles.start();
=== END ===

