  'approval-watch',
  H.when.crossing(approvalRate, {
    window: { lastDays: 7 },
    minSamples: 50,
    enter: { below: 0.9 },
    exit: { above: 0.95 },
  }),
)
  .create(audits, event =>
    event.edge === 'entered'
      ? { category: event.group, openingRate: event.value, openingSamples: event.samples }
      : undefined,
  )
  .record(supportExperience, event =>
    event.edge === 'entered'
      ? {
          body: {
