  'model-error-watch',
  H.when.crossing(modelErrors, {
    window: { lastHours: 1 },
    minSamples: 20,
    enter: { above: 0.2 },
    exit: { below: 0.05 },
  }),
)
  .pause(conversations, event =>
    event.edge === 'entered'
      ? `model error rate ${event.value} over ${event.samples} invocations in the last hour`
      : undefined,
  )
  .resume(conversations, event =>
    event.edge === 'exited'
