const maxTwo = claudeCode.subscription('max-two', { configDir: H.env('CLAUDE_MAX_TWO_DIR') });
const maxThree = claudeCode.subscription('max-three', { configDir: H.env('CLAUDE_MAX_THREE_DIR') });
