  .states(review, current, suspended, churned);

const usageReport = H.command('usage-report')
  .input(z.object({ tenantId: z.string() }))
  .argv((i) => ['usage-report', '--tenant', i.tenantId, '--period', 'last-month'])
  .on(local)
