export const docsControl = H.control('docs-control', docs)
  .clients([claudeCode.supervisor('docs-supervisor', docsAccess, { port: H.slot.port(1) })]);

export async function main(): Promise<void> {
  await coding.start();
  await codingControl.serve();
  await docs.start();
