      if (!audit.ok) return ctx.fail(audit.error);
      deficits = audit.value.deficits;
      if (deficits.length === 0) return 'done';
    }
    return ctx.fail(`${deficits.length} deficits remain after ${ctx.params.rounds} rounds`);
  });

